/**
 * #4684: Claude Code honors `continueOnBlock` on prompt hooks only and drops
 * it on command hooks. #4685 removed the key from every ork command hook and
 * corrected the hook comments: goal-tracker and check-plugins-drift are full
 * blocks. Two documents kept the old story, that these hooks run with
 * `continueOnBlock:true` so a block only warns. This pins the docs to what
 * the hooks actually do.
 */

import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const HOOKS_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const DOCS = ['README.md', join('src', 'types.ts')];

function linesMentioning(rel: string): string[] {
  return readFileSync(join(HOOKS_ROOT, rel), 'utf8')
    .split('\n')
    .filter((line) => line.includes('continueOnBlock'));
}

describe('continueOnBlock claims match the hooks (#4684)', () => {
  it.each(DOCS)('%s never says a hook is registered with continueOnBlock:true', (rel) => {
    const offending = linesMentioning(rel).filter((line) => /continueOnBlock:\s*true/.test(line));
    expect(offending).toEqual([]);
  });

  it.each(DOCS)('%s never says an ork hook uses continueOnBlock', (rel) => {
    const offending = linesMentioning(rel).filter((line) => /continueOnBlock.{0,120}\bused by\b/.test(line));
    expect(offending).toEqual([]);
  });

  it('README still states the prompt-hook-only rule', () => {
    const lines = linesMentioning('README.md');
    expect(lines.some((line) => line.includes('valid on `type: "prompt"` hooks only'))).toBe(true);
  });
});
